      ];
      var borderColors = [
        '#2ecc71', '#e8a838', '#e8a838', '#e85d3a', '#c0392b'
      ];

      ChartManager.safeInit('sspChart', {
        type: 'bar',
        data: {
          labels: ['SSP1-1.9', 'SSP1-2.6', 'SSP2-4.5', 'SSP3-7.0', 'SSP5-8.5'],
          datasets: [{
            label: 'Projected warming by 2100 (°C)',
            data: [1.4, 1.8, 2.7, 3.6, 4.4],
            backgroundColor: gradientColors,
            borderColor: borderColors,
            borderWidth: 1,
            borderRadius: 6,
            borderSkipped: false
          }]
        },
        options: {
