          maintainAspectRatio: false,
          indexAxis: 'x',
          plugins: {
            tooltip: {
              enabled: true,
              padding: 12,
              cornerRadius: 8,
              callbacks: {
                label: function(ctx) { return ctx.raw + '°C by 2100'; }
              }
            },
            legend: { display: false }
