const { chromium } = require('playwright');
(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const errors = [];
  page.on('console', msg => { if (msg.type() === 'error') errors.push(msg.text()); });
  page.on('pageerror', err => errors.push(err.message));
  await page.setViewportSize({ width: 1685, height: 2384 });
  await page.goto('file:///app/output/poster.html', { waitUntil: 'networkidle' });
  await page.waitForTimeout(2000);
  if (errors.length > 0) {
    console.log('ERRORS:', errors.join('\n'));
  } else {
    console.log('No console errors');
  }
  // Check if chart canvas has content
  const hasChart = await page.evaluate(() => {
    var c = document.getElementById('sspChart');
    return c ? 'Canvas found, width:' + c.width + ' height:' + c.height : 'No canvas';
  });
  console.log('Chart check:', hasChart);
  // Check metrics count
  const metrics = await page.evaluate(() => document.querySelectorAll('.metric-card').length);
  console.log('Metric cards:', metrics);
  await browser.close();
})();
EOF
